    "translation": "江南又到了采莲的好时节，一片片碧绿的莲叶挨挨挤挤地铺满水面，多么茂盛呀！活泼的鱼儿在莲叶间游来游去，一会儿游到东边，一会儿游到西边，一会儿又钻到南边和北边，好像在跟我们玩捉迷藏呢！",
    "appreciation": "这首诗就像一幅会动的画！它不断地重复“鱼戏莲叶间”，让我们好像真的看到鱼儿在莲叶间快乐地游来游去。东、西、南、北四个方向写出来，就像小鱼在跳圆圈舞，读起来特别有节奏感。虽然整首诗很短，但江南水乡那种自由自在、生机勃勃的感觉全都跑出来了。",
    "background": "这是汉朝时候流传下来的一首民歌，是人们在采莲时唱的歌。那时候江南水乡到处是荷塘，每到夏天，人们划着小船去采莲蓬，一边采一边唱歌。这首歌可能就是采莲人随口唱出来的，后来被人记录下来，一直传唱了两千多年。",
    "author_info": "汉乐府是汉朝专门收集民间歌谣的音乐机构，里面的“乐”就是音乐的意思。这些民歌不是某一个人写的，而是老百姓口口相传创作出来的，就像今天我们听到的童谣一样。《江南》是其中最欢快的一首。",
    "notes": "汉乐府：原是汉初采诗制乐的官署，后来又专指汉代的乐府诗。汉惠帝时，有乐府令一官，可能当时已设有乐府。武帝时乐府规模扩大，成为一个专设的官署，掌管郊祀、巡行、朝会、宴飨时的音乐，兼管采集民间歌谣，以供统治者观风察俗，了解民情厚薄。这些采集来的歌谣和其他经乐府配曲入乐的诗歌即被后人称为乐府诗。田田：荷叶茂盛的样",
    "tags": [
      "古诗三百首",
      "民歌",
      "写景"
    ],
    "gwd_id": "ef9cd9ba44bb",
    "gwd_url": "https://www.guwendao.net/shiwenv_ef9cd9ba44bb.aspx",
    "translation_gwd": "江南又到了适宜采莲的季节了，莲叶浮出水面，挨挨挤挤，重重叠叠，迎风招展。在茂密如盖的荷叶下面，欢快的鱼儿在不停的嬉戏玩耍。\n一会儿在这儿，一会儿又忽然游到了那儿，说不清究竟是在东边，还是在西边，还是在南边，还是在北边。",
    "appreciation_gwd": "《江南》是一篇歌唱江南劳动人民采莲时愉快情景的民歌。此诗前三句点明采莲季节和地点，呈现出生动、秀美的江南景致；后四句以东、西、南、北四个方位并列，描述鱼儿嬉戏的情景。全诗格调清新活泼，诗人运用比拟、移情和复沓等手法，营造出江南水上采莲的优美意境。",
    "background_gwd": "《江南》是产生于汉代的一首采莲歌。关于此诗的创作背景，学界有不同的说法。有人说是一首情歌，“鱼戏莲叶”有暗喻男女欢爱的意思；也有人说这仅仅是写劳动生活的快乐。",
