    "translation": "鹅呀鹅呀，弯着长长的脖子朝着天空唱歌呢！一身雪白雪白的羽毛，轻轻地浮在绿绿的水面上；一双红红的脚掌，在水下慢慢拨动着清清的水波。你看，它多优雅，多漂亮，就像水面上的一只小白船！",
    "appreciation": "这是骆宾王七岁时写的诗，太厉害了对不对？他用最简单的语言画出了鹅最漂亮的样子。“白毛”“绿水”“红掌”“清波”，四种颜色放在一起，像一幅彩色画。鹅叫的声音“鹅鹅鹅”，小朋友一读就笑了，因为真的太像了！这首诗告诉我们，好诗不一定要很难懂，把看到的美说出来，就是最好的诗。",
    "background": "骆宾王写这首诗的时候才七岁，跟你们差不多大呢！有一天，家里来了一位客人，指着池塘里的鹅让他作诗。小骆宾王看着白鹅在水里游来游去，随口就念出了这首诗。客人听了大吃一惊，连连称赞他是个小神童。",
    "author_info": "骆宾王（约638-684年）是唐朝初年的大诗人，和王勃、杨炯、卢照邻一起被称为“初唐四杰”。他小时候就是有名的神童，长大了不仅诗写得好，还很有正义感。《咏鹅》是他最广为人知的作品。",
    "notes": "曲项：弯着脖子。歌：长鸣。拨：划动。",
