    "funTip": "古对今·雪景意境，一起读读吧～",
    "sceneId": "snow",
    "sceneName": "雪景",
    "bgTheme": "snow",
    "theme": "节日",
    "translation": "古代对应现代，圆形对应方形。寒冷的冬天对应炎热的夏天，春天的温暖对应秋天的凉爽。\n早晨对应傍晚，雪花对应霜冻。柔和的风对应细小的雨，早晨的霞光对应傍晚的太阳。\n桃子对应李子，柳树对应杨树，黄莺的歌声对应燕子的舞蹈，鸟儿的鸣叫对应花朵的香气。",
    "appreciation": "",
    "background": "",
    "author_info": "车万育，清诗人/文人。",
    "notes": "莺歌：莺啼婉转似歌，亦喻婉转悦耳的歌声。\n燕舞：燕子飞舞。",
