    "translation_gwd": "人出生之初，禀性本身都是善良的。\n天性也都相差不多，只是后天所处的环境不同和所受教育不同，彼此的习性才形成了巨大的差别。\n如果从小不好好教育，善良的本性就会发生改变。\n为了使人不变坏，最重要的方法就是要专心一致地去教育孩子。",
