    "funTip": "守株待兔·田野意境，一起读读吧～",
    "sceneId": "field",
    "sceneName": "田野",
    "bgTheme": "field",
    "theme": "节日",
    "translation": "宋国有个种地的农民，他的田地中有一截树桩。一天，一只跑得飞快的野兔撞在了树桩上，折断了脖子死了。于是，他便放下他的农具日日夜夜守在树桩子旁边，希望能再得到一只兔子。然而野兔是不可能再次得到了，而他自己也被宋国人耻笑。",
    "appreciation": "《守株待兔》是一则寓言故事，此文描绘了宋国一耕者的经历。一日，他在田中劳作，偶遇一只兔子奔跑中撞到树桩，颈折而死。这位耕者见状，便放弃手中的农具，守在树桩旁，期待再次得到这样的好运，然而，兔子没有再出现。这则故事寓意深远，警示人们不要因一时的侥幸成功而放弃持久的努力。耕者被瞬间的幸运所迷惑，放弃了辛勤的劳作，结果自然是空手而归，反成笑柄。它也告诫我们，偶然的成功不能持久，真正的成功需要持续的努力和耐心。",
    "background": "",
    "author_info": "韩非子，先秦诗人/文人。",
    "notes": "株：树桩。\n走：跑。\n触：撞到。\n折：折断。\n因：于是，就。\n释：放，放下。\n耒(lěi)：一种农具。\n冀：希望。\n复：又，再。\n得：得到。\n身：自己。\n为：被，表被动。",
    "tags": [
      "小学文言文",
      "寓言",
      "哲理"
    ],
    "gwd_id": "bf758d053fca",
    "gwd_url": "https://www.guwendao.net/shiwenv_bf758d053fca.aspx",
    "translation_gwd": "宋国有个种地的农民，他的田地中有一截树桩。一天，一只跑得飞快的野兔撞在了树桩上，折断了脖子死了。于是，他便放下他的农具日日夜夜守在树桩子旁边，希望能再得到一只兔子。然而野兔是不可能再次得到了，而他自己也被宋国人耻笑。",
    "appreciation_gwd": "《守株待兔》是一则寓言故事，此文描绘了宋国一耕者的经历。一日，他在田中劳作，偶遇一只兔子奔跑中撞到树桩，颈折而死。这位耕者见状，便放弃手中的农具，守在树桩旁，期待再次得到这样的好运，然而，兔子没有再出现。这则故事寓意深远，警示人们不要因一时的侥幸成功而放弃持久的努力。耕者被瞬间的幸运所迷惑，放弃了辛勤的劳作，结果自然是空手而归，反成笑柄。它也告诫我们，偶然的成功不能持久，真正的成功需要持续的努力和耐心。",
