    "gwd_url": "https://www.guwendao.net/shiwenv_1104052ed0fc.aspx",
    "translation_gwd": "炎帝的小女儿，名叫女娃。有一次，女娃去东海游玩，溺水身亡，再也没有回来，因此化为精卫鸟。经常口衔西山上的树枝和石块，用来填塞东海。",
    "appreciation_gwd": "这篇短文讲述炎帝之女溺亡于东海，化为神鸟精卫决心填平大海。此文文化内涵丰富，解读视角多样，从中表现出人类最本质、永恒的特征：对生存的恐慌，以及在这之上呈现出的人类独有的精神气质，亦显示了先民缘于最基本的生存而产生的文化意识，这里的生存仅是对生命的珍惜，缘于保存生命的初始本能。后世将这种危机意识逐渐推延到更深更广的程度，以象征人类百折不回的毅力和意志。",
    "background_gwd": "",
    "sentences": [
      {
        "text": "炎帝之少女",
        "py": "yán dì zhī shào nǚ"
      },
      {
        "text": "名曰女娃",
        "py": "míng yuē nǚ wá"
      },
      {
        "text": "女娃游于东海",
        "py": "nǚ wá yóu yú dōng hǎi"
      },
      {
        "text": "溺而不返",
        "py": "nì ér bù fǎn"
      },
      {
        "text": "故为精卫",
        "py": "gù wéi jīng wèi"
      },
      {
        "text": "常衔西山之木石",
        "py": "cháng xián xī shān zhī mù shí"
      },
      {
        "text": "以堙于东海",
        "py": "yǐ yīn yú dōng hǎi"
      }
    ]
