    "paragraphs": [
      "王戎七岁，尝与诸小儿游。",
      "看道边李树多子折枝，诸儿竞走取之，唯戎不动。",
      "人问之，答曰：“树在道边而多子，此必苦李。",
      "”取之，信然。"
    ],
