    "funTip": "王戎不取道旁李·边塞意境，一起读读吧～",
    "sceneId": "mountain",
    "sceneName": "边塞",
    "bgTheme": "mountain",
    "theme": "友情",
    "translation": "王戎七岁的时候，曾经和许多小孩一起嬉戏玩耍。他们看见路边李子树上果实累累，把树枝都压弯了。许多孩子都争相跑过去摘李子，只有王戎没有动。有人问他为什么不去摘李子，王戎回答说：“李树在路边竟然还有这么多李子，这一定是苦李子。”摘来一尝，确实如此。",
    "appreciation": "此文生动记叙了王戎不摘路边李的事件、与他人的问答和其心理过程。他年仅七岁，就展现出非凡的观察力和判断力，能够透过现象看本质，不被表面的诱惑所迷惑。这种智慧和定力，让人不禁为之赞叹；同时，这个故事也告诉我们，在面对诱惑时，应该保持冷静和理智，不要轻易被表面的现象所迷惑，要学会用智慧和判断力去分析问题，做出正确的选择。",
    "background": "",
    "author_info": "刘义庆，南北朝诗人/文人。",
    "notes": "王戎：西晋琅琊（今属山东）人，自幼聪明过人，为“竹林七贤”之一，官至尚书令，司徒。\n尝：曾经。\n诸：众多。\n游：嬉戏玩耍。\n子：李子。\n折枝：压弯树枝。\n竞走：争相地跑过去。\n竞：争逐。\n走：跑。\n唯：只有。\n展开阅读全文\n简析\n此文生动记叙了王戎不摘路边李的事件、与他人的问答和其心理过程。他年仅七岁，就展现出非凡的观察力和判断力，能够透过现象看本质，不被表面的诱惑所迷惑。这种智慧和定力，让人不禁为之赞叹；同时，这个故事也告诉我们，在面对诱惑时，应该保持冷静和理智，不要轻易被表面的现象所迷惑，要学会用智慧和判断力去分析问题，做出正确的选择。",
    "tags": [
      "小学文言文",
      "故事",
      "哲理"
    ],
    "gwd_id": "cfeddc2459c2",
