    "funTip": "嫦娥·池塘意境，一起读读吧～",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "亲情",
    "translation": "室内烛光越来越黯淡，云母屏风上笼罩着一层深深的暗影，银河渐渐斜落，晨星也隐没低沉。\n嫦娥应该后悔偷取了长生不老之药，如今只能空对碧海青天夜夜孤寂。",
    "appreciation": "《嫦娥》是一首七言绝句。此诗咏叹嫦娥在月中的孤寂情景，抒发诗人自伤之情。前两句分别描写室内、室外的环境，渲染空寂清冷的气氛，表现了诗人忧愁、怀思的情绪；后两句是其在一宵痛苦思忆之后产生的感想，表达了一种孤寂感，这种孤寂感融入了诗人独特的现实人生感受，而含有更丰富深刻的意蕴。在黑暗污浊的现实包围中，诗人精神上力图摆脱尘俗，追求高洁的境界，而追求的结果往往使自己陷于更孤独的境地。他既不甘变心从俗，又难以忍受孤苦寂寞的煎熬，十分矛盾纠葛。全诗情调感伤，想象奇幻，意蕴丰富。",
    "background": "作者终身处于牛李党争的夹缝之中，一生很不得志。牛李党争的实质就是太监当权，本诗就是讽刺太监当权的黑暗、讽刺宪宗的皇权旁落。子曰：“邦有道，则仕；邦无道，则可卷而怀之。”",
    "author_info": "李商隐，唐诗人/文人。",
    "notes": "嫦娥：原作“姮娥”，神话中的月亮女神，传说是大羿的妻子。\n云母屏风：以云母石制作的屏风。云母，一种矿物，板状，晶体透明有光泽，古代常用来装饰窗户、屏风等物。\n深：暗淡。\n长河：银河。\n晓星：晨星。或\n展开阅读全文\n创作背景\n作者终身处于牛李党争的夹缝之中，一生很不得志。牛李党争的实质就是太监当权，本诗就是讽刺太监当权的黑暗、讽刺宪宗的皇权旁落。子曰：“邦有道，则仕；邦无道，则可卷而怀之。”",
    "tags": [
      "唐诗三百首",
      "小学古诗",
      "七言绝句"
    ],
    "gwd_id": "caef25db347c",
