    "translation": "中华大地需要依靠风雷般的力量来激发活力，死气沉沉的局面让人无比悲哀。我劝老天爷重新振作精神，不拘一格地让各种人才脱颖而出吧！",
    "appreciation": "这首诗写于清朝末年，国家内忧外患，死气沉沉。诗人用「万马齐喑」形容当时万马无声的沉闷局面，用「风雷」呼唤改革的力量。「我劝天公重抖擞，不拘一格降人才」这两句充满了对未来的期盼——诗人期盼出现一场大变革，让有才能的人都得到重用，来拯救这个危亡的国家。",
    "background": "龚自珍生活在清朝由盛转衰的时期，看到国家越来越腐败落后，心中非常焦急。1839年，他辞官离开北京，写了315首《己亥杂诗》，记录自己的所见所闻和内心感受。这首诗表达了他对变革的强烈呼唤。",
    "author_info": "龚自珍（1792—1841），字璱人，号定盦，清代思想家、文学家。他是中国近代启蒙思想的先驱，他的诗充满了改革精神和爱国热忱。代表作有《己亥杂诗》。",
    "notes": "九州：中国的别称之一。分别是：冀州、兖州、青州、徐州、扬州、荆州、梁州、雍州和豫州。生气：生气勃勃的局面。恃（shì）：依靠。万马齐喑：所有的马都沉寂无声。比喻社会政局毫无生气。喑（yīn），沉默，不说话。天公：造物主。抖擞：振作，奋发。降：降生，降临。",
