    "funTip": "少年中国说·池塘意境，一起读读吧～",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "节日",
    "translation": "所以说今天的责任，不在别人身上，全在我们少年身上。少年一代有智慧国家就智慧，少年富足国家就富足，少年强大国家就强大，少年独立国家就独立，少年自由国家就自由，少年进步国家就进步，少年胜过欧洲，国家就胜过欧洲，少年称雄于世界，国家就称雄于世界。",
    "appreciation": "此篇文章极力歌颂少年的朝气蓬勃，热切希望出现“少年中国”，意图振奋人民的精神，启迪其心志。全文不拘格式，多用比喻，具有强烈的鼓励性和进取精神。它犹如一曲慷慨激昂的青春赞歌，充满了对少年中国的热切期望和无限憧憬，以一种诗意的方式，描绘了少年与国家的紧密关系，展望少年所承载的国家和民族的未来。",
    "background": "《少年中国说》写于1900年，正在戊戌变法后，作者梁启超流亡日本之时。当时八国联军制造舆论，污蔑中国是“老大帝国”，是“东亚病夫”，是“一盘散沙”，不能自立，只能由列强共管或瓜分。而中国人中，有一些无知昏庸者，也跟着叫嚷“中国不亡是无天理”“任何列强三日内就可以灭亡中国”，散布悲观情绪，民族危机空前严重。为了驳斥帝国主义分子的无耻滥言，也纠正国内一些人自暴自弃、崇洋媚外的奴性心理，梁启超适时地写出这篇《少年中国说》，此文便节选自《少年中国说》。",
    "author_info": "梁启超，近现诗人/文人。",
    "notes": "",
