    "funTip": "观书有感·其二·池塘意境，一起读读吧～",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "节日",
    "translation": "昨天夜晚江边的春水大涨，那艘大船就像一片羽毛一般轻盈。\n以往花费许多力量也不能推动它，今天却能在江水中央自在漂流。",
    "appreciation": "《观书有感·其二》是一首七言绝句。此诗借事说理，借助巨舰无人推动却能自由航行在水中这一形象以阐明艺术灵感的勃发，足以使得艺术创作流畅自如这一道理，也可以理解为创作艺术要基本功夫到家，则熟能生巧，驾驭自如。全诗寓哲理于生动形象的比喻之中，不堕理障而富于理趣，一直为人传诵。",
    "background": "公元1196年（庆元二年），为避权臣韩侂胄之祸，朱熹与门人黄干、蔡沈、黄钟来到新城福山双林寺侧的武夷堂讲学。应南城县上塘蛤蟆窝村吴伦、吴常兄弟之邀，到该村讲学，为吴氏厅堂书写“荣木轩”，并为吴氏兄弟创办的社仓撰写了《社仓记》，还在该村写下了《观书有感二首》。这是组诗的第二首。",
    "author_info": "朱熹，宋诗人/文人。",
    "notes": "蒙冲：古代攻击性很强的战舰名，这里指大船。\n一毛轻：像一片羽毛一般轻盈。\n向来：原先，指春水上涨之前。\n推移力：指浅水时行船困难，需人推挽而行。\n中流：河流的中心。",
    "tags": [
      "幼儿古诗",
      "宋诗三百首",
      "千家诗"
    ],
    "gwd_id": "dd1c97accf6e",
    "gwd_url": "https://www.guwendao.net/shiwenv_dd1c97accf6e.aspx",
    "translation_gwd": "昨天夜晚江边的春水大涨，那艘大船就像一片羽毛一般轻盈。\n以往花费许多力量也不能推动它，今天却能在江水中央自在漂流。",
    "appreciation_gwd": "《观书有感·其二》是一首七言绝句。此诗借事说理，借助巨舰无人推动却能自由航行在水中这一形象以阐明艺术灵感的勃发，足以使得艺术创作流畅自如这一道理，也可以理解为创作艺术要基本功夫到家，则熟能生巧，驾驭自如。全诗寓哲理于生动形象的比喻之中，不堕理障而富于理趣，一直为人传诵。",
    "background_gwd": "公元1196年（庆元二年），为避权臣韩侂胄之祸，朱熹与门人黄干、蔡沈、黄钟来到新城福山双林寺侧的武夷堂讲学。应南城县上塘蛤蟆窝村吴伦、吴常兄弟之邀，到该村讲学，为吴氏厅堂书写“荣木轩”，并为吴氏兄弟创办的社仓撰写了《社仓记》，还在该村写下了《观书有感二首》。这是组诗的第二首。",
