    "paragraphs": [
      "楚人有鬻盾与矛者，誉之曰：“吾盾之坚，物莫能陷也。",
      "”又誉其矛曰：“吾矛之利，于物无不陷也。",
      "”或曰：“以子之矛陷子之盾，何如？",
      "”其人弗能应也。",
      "夫不可陷之盾与无不陷之矛，不可同世而立。"
    ],
