    "funTip": "自相矛盾·山水意境，一起读读吧～",
    "sceneId": "generic",
    "sceneName": "山水",
    "bgTheme": "generic",
    "theme": "友情",
    "translation": "有一个楚国人，既卖盾又卖矛。他夸耀自己的盾，说：“我的盾坚固无比，没有什么东西能够穿透它。”又夸耀自己的矛，说：“我的矛锋利极了，任何坚固的东西都穿得透。”有人问他：“如果用您的矛刺您的盾，结果会怎么样呢？”那人一句话也回答不上来。什么都不能刺穿的盾与什么都能刺穿的矛，不可能同时存在于这个世界上。",
    "appreciation": "《自相矛盾》出自《韩非子·难一》，这则故事以简洁明了的语言揭示了自相矛盾的逻辑错误。它告诉我们，在陈述观点或推销产品时，必须保持逻辑的一致性，否则就会陷入自相矛盾的境地。这种错误不仅在言语表达中需要避免，在实际生活和工作中也应该警惕。同时，这个故事也以一种幽默的方式提醒了在自我宣传和推销时，过分的夸大其词可能会让人陷入尴尬窘境。",
    "background": "",
    "author_info": "韩非，先秦诗人/文人。",
    "notes": "矛：古代用来刺杀敌人的长柄兵器，矛的基本形制有狭叶、阔叶、长叶、叶刃带系和凹口骹式等。\n盾：盾牌,古代作战时遮挡刀剑用。\n誉：赞誉，夸耀。\n曰：说，讲。\n吾：我。\n陷：穿透、刺穿的意思 。\n展开阅读全文\n简析\n《自相矛盾》出自《韩非子·难一》，这则故事以简洁明了的语言揭示了自相矛盾的逻辑错误。它告诉我们，在陈述观点或推销产品时，必须保持逻辑的一致性，否则就会陷入自相矛盾的境地。这种错误不仅在言语表达中需要避免，在实际生活和工作中也应该警惕。同时，这个故事也以一种幽默的方式提醒了在自我宣传和推销时，过分的夸大其词可能会让人陷入尴尬窘境。",
