    "funTip": "杨氏之子·山林意境，一起读读吧～",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "亲情",
    "translation": "梁国一户姓杨的人家家里有一个九岁的儿子，非常聪明。孔君平来拜见他的父亲，恰巧他父亲不在，于是便叫他出来。他为孔君平端来水果，水果中有杨梅，孔君平指着杨梅给孩子看，并说：“这是你家的水果。”杨氏子马上回答说：“没听说孔雀是先生您家的鸟。”",
    "appreciation": "本文讲述了梁国姓杨的一家中的九岁男孩的故事。文中描述了杨氏之子的聪明，把杨氏之子巧妙的回答描写得惟妙惟肖，幽默风趣。 全文阐明了要学会随机应变、考虑再三，用智慧和勇气解决问题的道理。",
    "background": "《杨氏之子》选自《世说新语·言语》，这部书是一部主要记载汉末至晋代士族阶层言谈轶事的小说。",
    "author_info": "刘义庆，南北朝诗人/文人。",
    "notes": "氏：姓氏，表示家族的姓。\n甚：非常。\n惠：惠同“慧”，智慧的意思。\n孔君平：孔坦，字君平，官至廷尉。\n诣：拜见。\n乃：就；于是。\n设：摆放，摆设。\n示：给……看。\n曰：说。\n未闻：没有听说过。未：没有。\n夫子\n展开阅读全文\n创作背景\n《杨氏之子》选自《世说新语·言语》，这部书是一部主要记载汉末至晋代士族阶层言谈轶事的小说。",
    "tags": [
      "儿童",
      "小学文言文",
      "笔记文"
    ],
    "gwd_id": "af4715c0208f",
    "gwd_url": "https://www.guwendao.net/shiwenv_af4715c0208f.aspx",
    "translation_gwd": "梁国一户姓杨的人家家里有一个九岁的儿子，非常聪明。孔君平来拜见他的父亲，恰巧他父亲不在，于是便叫他出来。他为孔君平端来水果，水果中有杨梅，孔君平指着杨梅给孩子看，并说：“这是你家的水果。”杨氏子马上回答说：“没听说孔雀是先生您家的鸟。”",
    "appreciation_gwd": "本文讲述了梁国姓杨的一家中的九岁男孩的故事。文中描述了杨氏之子的聪明，把杨氏之子巧妙的回答描写得惟妙惟肖，幽默风趣。 全文阐明了要学会随机应变、考虑再三，用智慧和勇气解决问题的道理。",
    "background_gwd": "《杨氏之子》选自《世说新语·言语》，这部书是一部主要记载汉末至晋代士族阶层言谈轶事的小说。",
