    "funTip": "鸟鸣涧·山林意境，一起读读吧～",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "节日",
    "translation": "寂静的山谷中，只有春桂花在无声地飘落，宁静的夜色中春山一片空寂。\n月亮升起月光照耀大地时惊动了山中栖鸟，在春天的溪涧里不时地鸣叫。",
    "appreciation": "《鸟鸣涧》是一首山水诗。此诗描绘春夜空山幽深而美丽的景色，侧重于表现夜间春山的宁静幽美。全诗紧扣“静”字着笔，极似一幅风景写生画。诗人用花落、月出、鸟鸣等活动着的景物，突出表现了月夜春山的幽静，取得了以动衬静的艺术效果，生动地勾勒出一幅“鸟鸣山更幽”的诗情画意图。全诗旨在写静，却以动景处理，这种反衬的手法极见诗人的禅心与禅趣。",
    "background": "这首诗应当是作于713—741年（唐开元）年间游历江南之时，当时正是盛唐时期。此诗是王维题友人皇甫岳所居的云溪别墅所写的组诗《皇甫岳云溪杂题五首》的第一首，是诗人寓居在今绍兴县东南五云溪（即若耶溪）的作品。",
    "author_info": "王维，唐诗人/文人。",
    "notes": "鸟鸣涧：鸟儿在山涧中鸣叫。\n人闲：指没有人事活动相扰。\n闲：安静、悠闲，含有人声寂静的意思。\n桂花：春桂，现在叫山矾，也有人叫它山桂花。\n春山：春日的山。亦指春日山中。\n空：空寂、空空荡荡。空虚。这时形容山中寂静，无声，好像空无所有。\n月出：月亮升起。\n惊：惊动，扰乱。\n山鸟：山中的鸟。\n时鸣：偶尔（时而）啼叫。\n展开阅读全文\n创作背景\n这首诗应当是作于713—741年（唐开元）年间游历江南之时，当时正是盛唐时期。此诗是王维题友人皇甫岳所居的云溪别墅所写的组诗《皇甫岳云溪杂题五首》的第一首，是诗人寓居在今绍兴县东南五云溪（即若耶溪）的作品。",
    "tags": [
      "五言绝句",
      "小学古诗",
      "幼儿古诗"
    ],
    "gwd_id": "8ec950bd1395",
    "gwd_url": "https://www.guwendao.net/shiwenv_8ec950bd1395.aspx",
    "translation_gwd": "寂静的山谷中，只有春桂花在无声地飘落，宁静的夜色中春山一片空寂。\n月亮升起月光照耀大地时惊动了山中栖鸟，在春天的溪涧里不时地鸣叫。",
    "appreciation_gwd": "《鸟鸣涧》是一首山水诗。此诗描绘春夜空山幽深而美丽的景色，侧重于表现夜间春山的宁静幽美。全诗紧扣“静”字着笔，极似一幅风景写生画。诗人用花落、月出、鸟鸣等活动着的景物，突出表现了月夜春山的幽静，取得了以动衬静的艺术效果，生动地勾勒出一幅“鸟鸣山更幽”的诗情画意图。全诗旨在写静，却以动景处理，这种反衬的手法极见诗人的禅心与禅趣。",
    "background_gwd": "这首诗应当是作于713—741年（唐开元）年间游历江南之时，当时正是盛唐时期。此诗是王维题友人皇甫岳所居的云溪别墅所写的组诗《皇甫岳云溪杂题五首》的第一首，是诗人寓居在今绍兴县东南五云溪（即若耶溪）的作品。",
