    "funTip": "宿建德江·池塘意境，一起读读吧～",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "节日",
    "translation": "把船停泊在烟雾弥漫的沙洲旁，日落时新愁又涌上了心头。\n原野无边无际，远处的天空比近处的树林还要低；江水清清，明月仿似更与人相亲。",
    "appreciation": "《宿建德江》是一首山水诗，刻画了秋江暮色，是唐人五绝中的写景名篇。诗人把小船停靠在烟雾迷蒙的江边思忆往昔，以舟泊暮宿作为自己抒发感情的归宿，流露出羁旅之思。首联点题，为下文写景抒情作铺垫；颔联中“日暮”是“客愁新”的原因；颈、尾两联中，因为“野旷”所以天低于树，因为“江清”所以月能近人，将天和树、人和月的关系，写得恰切逼真。此诗前两句为触景生情，后两句为借景抒情，描写了清新的秋夜，细腻地表现了景物特点，其格调淡而有味、含而不露，自然流出、风韵天成，颇有特色。",
    "background": "公元730年（唐玄宗开元十八年）孟浩然离开家乡赶赴洛阳，再漫游吴越。《宿建德江》应当就是在其漫游吴越时写下的，与《问舟子》是同一时期的作品。",
    "author_info": "孟浩然，唐诗人/文人。",
    "notes": "建德江：指新安江流经建德（今属浙江）西部的一段江水。\n移舟：划动小船。泊：停船靠岸。\n烟渚（zhǔ）：指江中雾气笼罩的小沙洲。烟：一作“幽”。\n渚：水中小块陆地。《尔雅·释水》：“水中可居者曰洲，小洲曰渚。”\n客：指作者自己。\n愁：为思乡而忧思不堪。\n野：原野。旷：空阔远大。\n天低树：天幕低垂，好像和树木相连。\n月近人：倒映\n展开阅读全文\n创作背景\n公元730年（唐玄宗开元十八年）孟浩然离开家乡赶赴洛阳，再漫游吴越。《宿建德江》应当就是在其漫游吴越时写下的，与《问舟子》是同一时期的作品。",
    "tags": [
      "唐诗三百首",
      "幼儿古诗",
      "写景抒情"
    ],
