    "funTip": "七律·长征·雪景意境，一起读读吧～",
    "sceneId": "snow",
    "sceneName": "雪景",
    "bgTheme": "snow",
    "theme": "爱国",
    "translation": "红军不怕万里长征路上的一切艰难困苦，把千山万水都看得极为平常。\n五岭山脉绵延不绝，可在红军眼里不过像翻腾着的细小波浪；乌蒙山高大雄伟，在红军眼里也不过像在脚下滚过的泥丸。\n金沙江浊浪滔天，湍急的流水拍击着高耸的山崖，溅起阵阵雾水，像是冒出蒸汽一样。大渡河险桥横架，晃动着凌空高悬的根根铁索，寒意阵阵。\n更加令人欣喜的是千里岷山，皑皑白雪，红军翻越过去以后人人心情开朗，个个笑逐颜开。",
    "appreciation": "《七律·长征》是一首七言律诗。回顾长征一年来所战胜的无数艰难险阻，诗人满怀喜悦的战斗豪情。全诗高度概括了长征路上的各种艰难险阻，诗人通过生动典型的事例，热情洋溢地赞扬了中国工农红军不畏艰难，英勇顽强的革命英雄主义和乐观主义精神。此诗气势磅礴、气魄宏伟，格调高昂、笔力雄健。其不仅大处雄浑，节奏强烈，而且小处精细，抑扬顿挫。诗中对仗极为工整，用词颇为精妙，对张牙舞爪、穷凶极恶的敌人不置一字，视之若无，这种傲视山川的夺人之气，非百战百胜、总揽全局的三军统帅、一代伟人而不能拥有。",
    "background": "《七律·长征》写于1935年9月下旬，10月定稿。这首七律是作于红军战士越过岷山后，长征即将胜利结束前不久的途中。作为红军的领导人，毛泽东在经受了无数次考验后，如今，曙光在前，胜利在望，他心潮澎湃，满怀豪情地写下了这首壮丽的诗篇。",
    "author_info": "毛泽东，近现诗人/文人。",
    "notes": "七律：七律是律诗的一种，每篇一般为八句，每句七个字，分四联：首联、颔联、颈联和尾联；偶句末一字押平声韵，首句末字可押可不押，必须一韵到底\n展开阅读全文\n创作背景\n《七律·长征》写于1935年9月下旬，10月定稿。这首七律是作于红军战士越过岷山后，长征即将胜利结束前不久的途中。作为红军的领导人，毛泽东在经受了无数次考验后，如今，曙光在前，胜利在望，他心潮澎湃，满怀豪情地写下了这首壮丽的诗篇。",
