    "funTip": "伯牙鼓琴·山林意境，一起读读吧～",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "亲情",
    "translation": "伯牙弹琴，锺子期听他弹琴。伯牙在弹琴时心里想着高山，锺子期说：“你弹得真好呀，像大山一样高峻。”不一会儿，伯牙心里又想到流水，锺子期又说：“你弹得真好呀，就像那奔腾不息的流水。”锺子期死了以后，伯牙摔琴断弦，终生不再弹琴，认为世上再没有值得他为之弹琴的人了。",
    "appreciation": "《伯牙鼓琴》是讲述知音的故事，俞伯牙与锺子期是一对千古传诵的至交典范。伯牙善于演奏，锺子期善于欣赏，这就是“知音”一词的由来。后锺子期因病亡故，伯牙悲痛万分，认为这世上再也不会有知音了，天下再不会有人像锺子期一样能体会他演奏的意境。所以就把自己最心爱的琴摔断，挑断琴弦，终生不再弹琴。人生苦短，知音难求；云烟万里，佳话千载，友谊的基础是互相理解，而其最形象、最深刻的阐释，莫过于伯牙与子期的故事；此文流传至今并给人历久弥新的启迪，确立了中华民族高尚的人际关系与友情的标准。",
    "background": "",
    "author_info": "《吕氏春秋》，先秦诗人/文人。",
    "notes": "本文选自《吕氏春秋·本味》 。\n鼓：弹奏。\n听：倾听。\n方：才，刚刚。\n志在太山：心中想到高山。\n太山：泛指大山。高山。一说指东岳泰山。\n曰：说。\n善哉：赞美之词，有夸奖的意思。即“好啊” 、“妙啊”或“太棒了”。善\n展开阅读全文\n简析\n《伯牙鼓琴》是讲述知音的故事，俞伯牙与锺子期是一对千古传诵的至交典范。伯牙善于演奏，锺子期善于欣赏，这就是“知音”一词的由来。后锺子期因病亡故，伯牙悲痛万分，认为这世上再也不会有知音了，天下再不会有人像锺子期一样能体会他演奏的意境。所以就把自己最心爱的琴摔断，挑断琴弦，终生不再弹琴。人生苦短，知音难求；云烟万里，佳话千载，友谊的基础是互相理解，而其最形象、最深刻的阐释，莫过于伯牙与子期的故事；此文流传至今并给人历久弥新的启迪，确立了中华民族高尚的人际关系与友情的标准。",
    "tags": [
      "小学文言文",
      "音乐",
      "知音"
    ],
