    "translation_gwd": "伯牙弹琴，锺子期听他弹琴。伯牙在弹琴时心里想着高山，锺子期说：“你弹得真好呀，像大山一样高峻。”不一会儿，伯牙心里又想到流水，锺子期又说：“你弹得真好呀，就像那奔腾不息的流水。”锺子期死了以后，伯牙摔琴断弦，终生不再弹琴，认为世上再没有值得他为之弹琴的人了。",
    "appreciation_gwd": "《伯牙鼓琴》是讲述知音的故事，俞伯牙与锺子期是一对千古传诵的至交典范。伯牙善于演奏，锺子期善于欣赏，这就是“知音”一词的由来。后锺子期因病亡故，伯牙悲痛万分，认为这世上再也不会有知音了，天下再不会有人像锺子期一样能体会他演奏的意境。所以就把自己最心爱的琴摔断，挑断琴弦，终生不再弹琴。人生苦短，知音难求；云烟万里，佳话千载，友谊的基础是互相理解，而其最形象、最深刻的阐释，莫过于伯牙与子期的故事；此文流传至今并给人历久弥新的启迪，确立了中华民族高尚的人际关系与友情的标准。",
