    "funTip": "书戴嵩画牛·草地意境，一起读读吧～",
    "sceneId": "grass",
    "sceneName": "草地",
    "bgTheme": "grass",
    "theme": "节日",
    "translation": "蜀中有一位杜处士，喜好书画，珍藏的书画作品有数百件。其中有戴嵩画的《斗牛图》一幅，他特别喜爱，于是用锦缎作画套，又用玉装饰卷轴，并经常随身携带。",
    "appreciation": "《书戴嵩画牛》是一篇散文。此文先写杜处士爱好书画，尤为珍惜戴嵩所作《斗牛图》一轴；然后在此铺垫基础上突出一牧童拊掌大笑斗牛画的情景；最后以古语结束全篇，暗讥当政者不尊重现实而胡乱变法改制的错误行为。全篇短小精悍，情趣盎然，语言流畅明快，颇为生动，阐明了绘画要讲求形似，寓含着艺术源于生活的深刻道理。",
    "background": "此文作于熙宁元年（公元1068年），其时苏轼因父丧归蜀。一说此文创作时间不详，可能是元祐年间苏轼在京师任翰林学士、知制诰时所作。",
    "author_info": "苏轼，宋诗人/文人。",
    "notes": "戴嵩（sōng）：唐代画家，善画牛，有《斗牛图》。\n蜀中：四川。杜处（chǔ）士：不详。苏轼有《\n展开阅读全文\n创作背景\n此文作于熙宁元年（公元1068年），其时苏轼因父丧归蜀。一说此文创作时间不详，可能是元祐年间苏轼在京师任翰林学士、知制诰时所作。",
    "tags": [
      "寓理",
      "故事",
      "小学文言文"
    ],
