    "funTip": "菩萨蛮·大柏地·田野意境，一起读读吧～",
    "sceneId": "field",
    "sceneName": "田野",
    "bgTheme": "field",
    "theme": "节日",
    "translation": "天上挂着七色的彩虹，而又是谁手持着彩虹在空中翩翩起舞？黄昏雨之后又见夕阳，苍翠的群山仿如层层军阵。\n当年这里曾经进行了一次激烈的苦战，子弹穿透了前面村子的墙壁。那前村墙壁上留下的累累弹痕，把这里装扮得更加美丽。",
    "appreciation": "此词以欢快的笔调，描绘了一幅色彩斑斓的大柏地雨后的壮丽景色。词人抚今追昔，揭示革命战争的重大意义，热情讴歌了人民革命战争，流露出一种胜利后的宽慰和乐观情绪。全词动态描写景物、巧妙运用联想，主观的情志美与客观的自然美、社会美实现了统一，情景交融，富有韵味。",
    "background": "1929年，毛泽东和朱德、陈毅等率红军主力三千六百余人在这一年的早春离开了井冈山，向赣南进击。由于敌军重兵围追，又由于来到外地，人生地不熟，红四军沿途五战皆告失利。后红军在瑞金以北约30公里处的大柏地麻子坳布下口袋阵。自第二日下午3时一直激战到次日正午，终于击溃敌军，取得这次转战以来首次重大胜利。而胜利之地就是大柏地。1933年夏天毛泽东因从事调研工作，领导中央苏区的查田运动重返大柏地，面对昔日金戈铁马的战场，他触景生情，回忆往事，欣然命笔，写下了此诗。",
    "author_info": "毛泽东，近现诗人/文人。",
    "notes": "菩萨蛮：词牌名，本唐教坊曲，后用为词牌，也用作曲牌。亦作《菩萨鬘》，又名《子夜歌》、《重叠金》、《花溪碧》、《晚云烘日》等。另有《菩萨蛮引》、《菩萨蛮慢》。《菩萨蛮》也是曲牌名，属北曲正宫，字句格律与词牌前半阕同，用在套曲中。\n大柏地：乡名，位于江西省瑞金市北部，距市区30公里，素有“瑞金北大门”之称，319国道横贯\n展开阅读全文\n创作背景\n1929年，毛泽东和朱德、陈毅等率红军主力三千六百余人在这一年的早春离开了井冈山，向赣南进击。由于敌军重兵围追，又由于来到外地，人生地不熟，红四军沿途五战皆告失利。后红军在瑞金以北约30公里处的大柏地麻子坳布下口袋阵。自第二日下午3时一直激战到次日正午，终于击溃敌军，取得这次转战以来首次重大胜利。而胜利之地就是大柏地。1933年夏天毛泽东因从事调研工作，领导中央苏区的查田运动重返大柏地，面对昔日金戈铁马的战场，他触景生情，回忆往事，欣然命笔，写下了此诗。",
    "tags": [
      "中国诗词大会2024",
      "中国诗词大会2023",
      "写景"
    ],
    "gwd_id": "97f3412c43e2",
    "gwd_url": "https://www.guwendao.net/shiwenv_97f3412c43e2.aspx",
    "translation_gwd": "天上挂着七色的彩虹，而又是谁手持着彩虹在空中翩翩起舞？黄昏雨之后又见夕阳，苍翠的群山仿如层层军阵。\n当年这里曾经进行了一次激烈的苦战，子弹穿透了前面村子的墙壁。那前村墙壁上留下的累累弹痕，把这里装扮得更加美丽。",
    "appreciation_gwd": "此词以欢快的笔调，描绘了一幅色彩斑斓的大柏地雨后的壮丽景色。词人抚今追昔，揭示革命战争的重大意义，热情讴歌了人民革命战争，流露出一种胜利后的宽慰和乐观情绪。全词动态描写景物、巧妙运用联想，主观的情志美与客观的自然美、社会美实现了统一，情景交融，富有韵味。",
    "background_gwd": "1929年，毛泽东和朱德、陈毅等率红军主力三千六百余人在这一年的早春离开了井冈山，向赣南进击。由于敌军重兵围追，又由于来到外地，人生地不熟，红四军沿途五战皆告失利。后红军在瑞金以北约30公里处的大柏地麻子坳布下口袋阵。自第二日下午3时一直激战到次日正午，终于击溃敌军，取得这次转战以来首次重大胜利。而胜利之地就是大柏地。1933年夏天毛泽东因从事调研工作，领导中央苏区的查田运动重返大柏地，面对昔日金戈铁马的战场，他触景生情，回忆往事，欣然命笔，写下了此诗。",
