    "translation": "孔子向东游历，见到两个小孩在争辩，就问他们在争辩的原因。\n一个小孩子说：“我认为太阳刚刚升起的时候距离人近，而正午的时候距离人远。”\n另一个小孩说：“我认为太阳刚刚升起的时候，距离人比较远，而正午的时候距离人比较近。”\n一个小孩儿说：“太阳刚出时像车的车盖一样大，到了中午时就如同盘子一般小了，这不是远小近大的道理吗？”\n另一个小孩儿说：“太阳刚出来时凉爽，到了正午的时候热得如同把手伸进热水中，这不是近的就感觉热，而远就觉得凉的道理吗？”\n孔子听了之后不能判断他们俩谁对谁错。\n两个小孩子笑着对孔子说：“是谁说你智慧\n展开阅读全文\n创作背景\n此文节选自《列子·汤问》第七章，文题是后人所加。此文记录的是春秋时期，两小孩与当时的大学问家孔子的故事。",
    "appreciation": "《两小儿辩日》是一篇散文，亦是一则极具教育意义的寓言故事。其记述了孔子路遇两个孩子在争辩太阳远近的问题，而孔子不能作决断之事。此文阐明了知识无穷、学无止境的道理，同时也赞扬了孔子实事求是、敢于承认自己学识不足的精神和古代人民敢于探求客观真理，并能独立思考、大胆质疑的品质。全文通过对话描写来表现人物、展开故事情节，使得人物形象清晰可见、栩栩如生。",
    "background": "此文节选自《列子·汤问》第七章，文题是后人所加。此文记录的是春秋时期，两小孩与当时的大学问家孔子的故事。",
    "author_info": "列御寇，先秦诗人/文人。",
