    "funTip": "卜算子·送鲍浩然之浙东·山林意境，一起读读吧～",
    "sceneId": "mountain",
    "sceneName": "山林",
    "bgTheme": "mountain",
    "theme": "节日",
    "translation": "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。如果你到江南能赶上春天，千万要把春天的景色留住。",
    "appreciation": "这是一首送别词，为送别友人之作。上片用“眼波”、“眉峰”比喻浙东山水，表明行人去处是令人向往的山清水秀之地；下片点明送别是在暮春时节，写离别思绪和对友人的深情祝愿，叮嘱友人“千万和春住”。词人虽写送别友人，却不落惜别伤感的窠臼，而是通过描写别时的景物和离人的行踪，祝愿友人“永葆青春”，表现出两人之间深长的友情和惜春之意。全词构思新颖，比喻巧妙，又语带双关，含而不露，写得妙趣横生，耐人寻味。",
    "background": "春末时节，王观在越州（今浙江绍兴）大都督府送别从客途返家（也可能是去探望在浙东的爱姬）的好友鲍浩然。词人家在如皋（一说高邮），欲归不得，写下此诗赠与好友。",
    "author_info": "王观，宋诗人/文人。",
    "notes": "卜算子：词牌名。北宋时盛行此曲。万树《词律》以为取义于“卖卜算命之人”。双调，四十四字，上下片各两仄韵。两结亦可酌增衬字，化五言句为六言句，于第三字豆。宋教坊复演为慢曲，《乐章集》入“歇指调”。八十九字，前片四仄韵，后片五仄韵。\n鲍浩然：生平不详，词人的朋友，家住浙江东路，简称浙东。\n水是眼波横：水像美人流动的眼波。古人常以秋水喻美人之眼，这里反用。\n展开阅读全文\n创作背景\n春末时节，王观在越州（今浙江绍兴）大都督府送别从客途返家（也可能是去探望在浙东的爱姬）的好友鲍浩然。词人家在如皋（一说高邮），欲归不得，写下此诗赠与好友。",
    "tags": [
      "宋词三百首",
      "小学古诗",
      "初中古诗"
    ],
