    "translation_gwd": "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。如果你到江南能赶上春天，千万要把春天的景色留住。",
    "appreciation_gwd": "这是一首送别词，为送别友人之作。上片用“眼波”、“眉峰”比喻浙东山水，表明行人去处是令人向往的山清水秀之地；下片点明送别是在暮春时节，写离别思绪和对友人的深情祝愿，叮嘱友人“千万和春住”。词人虽写送别友人，却不落惜别伤感的窠臼，而是通过描写别时的景物和离人的行踪，祝愿友人“永葆青春”，表现出两人之间深长的友情和惜春之意。全词构思新颖，比喻巧妙，又语带双关，含而不露，写得妙趣横生，耐人寻味。",
    "background_gwd": "春末时节，王观在越州（今浙江绍兴）大都督府送别从客途返家（也可能是去探望在浙东的爱姬）的好友鲍浩然。词人家在如皋（一说高邮），欲归不得，写下此诗赠与好友。",
    "sentences": [
      {
        "text": "水是眼波横",
        "py": "shuǐ shì yǎn bō héng"
      },
      {
        "text": "山是眉峰聚",
        "py": "shān shì méi fēng jù"
      },
      {
        "text": "欲问行人去那边",
        "py": "yù wèn xíng rén qù nǎ biān"
      },
      {
        "text": "眉眼盈盈处",
        "py": "méi yǎn yíng yíng chù"
      },
      {
        "text": "才始送春归",
        "py": "cái shǐ sòng chūn guī"
      },
      {
        "text": "又送君归去",
        "py": "yòu sòng jūn guī qù"
      },
      {
        "text": "若到江南赶上春",
        "py": "ruò dào jiāng nán gǎn shàng chūn"
      },
      {
        "text": "千万和春住",
        "py": "qiān wàn hé chūn zhù"
      }
    ]
