    "funTip": "浣溪沙·游蕲水清泉寺·庭院意境，一起读读吧～",
    "sceneId": "courtyard",
    "sceneName": "庭院",
    "bgTheme": "courtyard",
    "theme": "节日",
    "translation": "游玩蕲水的清泉寺，寺庙在兰溪的旁边，溪水向西流淌。\n山脚下兰草新抽的幼芽浸润在溪水中，松林间的沙路被雨水冲洗得一尘不染，傍晚时分，细雨萧萧，杜鹃声声。\n谁说人生就不能再回到少年时期？门前的溪水都还能向西边流淌！不要在老年感叹时光的飞逝啊！",
    "appreciation": "这首词表现了词人虽处困境仍老当益壮、自强不息的情志，洋溢着一种乐观向上的人生态度。上阕写暮春三月清泉寺幽雅的风光和环境，景色自然明丽，雅淡清美；下阕则抒发坚强、奋发的思想，词人即景取喻，深入浅出地表达了人生感悟，富含哲理，启人心智。全词即景抒慨，写景纯用白描，细致淡雅；抒发感慨时则昂扬振拔，充满力量，深刻隽永。",
    "background": "这首词表现了词人虽处困境仍老当益壮、自强不息的情志，洋溢着一种乐观向上的人生态度。上阕写暮春三月清泉寺幽雅的风光和环境，景色自然明丽，雅淡清美；下阕则抒发坚强、奋发的思想，词人即景取喻，深入浅出地表达了人生感悟，富含哲理，启人心智。全词即景抒慨，写景纯用白描，细致淡雅；抒发感慨时则昂扬振拔，充满力量，深刻隽永。",
    "author_info": "苏轼，宋诗人/文人。",
    "notes": "蕲qí水：县名，今湖北浠水县。\n浸：泡在水中。\n萧萧：形容雨声。\n子规：又叫杜宇、杜鹃、催归。它总是朝着北方鸣叫，六、七月鸣叫声更甚，昼夜不止，发出的声音极其哀切，犹如盼子回归，所以叫杜鹃啼归、这种鸟也叫子规。\n无再少：不能回到少年时代。\n展开阅读全文\n创作背景\n这首词是宋神宗元丰五年（1082）春三月作者游蕲水清泉寺时所作。元丰二年（1079），苏轼因诗中有所谓“讥讽朝廷”语，被罗织罪名入狱，史称“乌台诗案”。“乌台诗案”过后，于元丰三年（1080）二月被贬任黄州（今湖北黄冈）团练副使。蕲水县距黄州不远。《苏轼文集》卷六十八《书清泉寺词》：“黄州东南三十里，为沙湖，亦曰螺师店。余将买田其间，因往相田。得疾，闻麻桥人庞安时善医而聋，遂往求疗。安时虽聋，而颖悟过人，以手指画字，不尽数字，辄了人深意。余戏之云：‘余以手为口，君以眼为耳。皆一时异人也。’疾愈，与之同游清泉寺。寺在蕲水郭门外二里许。有王逸少洗笔泉，水极甘，下临兰溪，溪水西流。余作歌云。”这\n展开阅读全文\n简析\n这首词表现了词人虽处困境仍老当益壮、自强不息的情志，洋溢着一种乐观向上的人生态度。上阕写暮春三月清泉寺幽雅的风光和环境，景色自然明丽，雅淡清美；下阕则抒发坚强、奋发的思想，词人即景取喻，深入浅出地表达了人生感悟，富含哲理，启人心智。全词即景抒慨，写景纯用白描，细致淡雅；抒发感慨时则昂扬振拔，充满力量，深刻隽永。",
