    "funTip": "清平乐·春归何处·山水意境，一起读读吧～",
    "sceneId": "generic",
    "sceneName": "山水",
    "bgTheme": "generic",
    "theme": "节日",
    "translation": "春天将归向何处？现在的我却找不到春的踪迹。如果有人知道春天的去处，请叫它仍旧回来和我同住。\n可是又有谁会知道春天离开的踪迹呢？除非你问一问黄鹂鸟。但是没有人能够理解它迂回婉转的啼鸣声。看吧，它已经趁着风势飞过了那片蔷薇。",
    "appreciation": "《清平乐·春归何处》是一首感叹时光去而不返的惜春词，词人以凄婉的笔法，抒写了对春天逝去的沉痛和惋惜，体现出其对美好时光的热爱、眷恋、痴情和追求。上片写春天的归去，词人将春拟人化，起句发问，既点明寻春、惜春旨意，又透出爱春、伤春情绪。接着又以对春天的体贴关怀，写春去无痕；下片写夏季的到来，先以叹问点明春天已无踪迹，进一步表现惜春的沉痛，接着又添一层烦恼和沉痛。与一般惜春之词不同，这首词不以景物描写为主，而以浪漫主义的手法，专写寻春，表达对春天的爱恋。",
    "background": "公元1103年（崇宁二年）十二月，黄庭坚至崇宁同年二月才过洞庭，五、六月间方抵达广西宜州贬所。本首词就是作于贬谪宜州的翌年，即公元1105年（崇宁四年）。",
    "author_info": "黄庭坚，宋诗人/文人。",
    "notes": "寂寞：清静，寂静。\n无行路：没有留下春去的行踪。行路，指春天来去的踪迹。\n唤取：唤来。\n谁知：有谁知道春的踪迹。\n问取：呼唤，询问。取，语助词。\n黄鹂（lí）：黄鹂：又叫黄莺、黄鸟。身体黄色自眼部至头后部黑色，嘴淡红色，啼声非常悦耳，食森林中的害虫。益鸟。\n展开阅读全文\n创作背景\n公元1103年（崇宁二年）十二月，黄庭坚至崇宁同年二月才过洞庭，五、六月间方抵达广西宜州贬所。本首词就是作于贬谪宜州的翌年，即公元1105年（崇宁四年）。",
    "tags": [
      "宋词三百首",
      "婉约",
      "春天"
    ],
    "gwd_id": "315cf2d8892b",
    "gwd_url": "https://www.guwendao.net/shiwenv_315cf2d8892b.aspx",
    "translation_gwd": "春天将归向何处？现在的我却找不到春的踪迹。如果有人知道春天的去处，请叫它仍旧回来和我同住。\n可是又有谁会知道春天离开的踪迹呢？除非你问一问黄鹂鸟。但是没有人能够理解它迂回婉转的啼鸣声。看吧，它已经趁着风势飞过了那片蔷薇。",
    "appreciation_gwd": "《清平乐·春归何处》是一首感叹时光去而不返的惜春词，词人以凄婉的笔法，抒写了对春天逝去的沉痛和惋惜，体现出其对美好时光的热爱、眷恋、痴情和追求。上片写春天的归去，词人将春拟人化，起句发问，既点明寻春、惜春旨意，又透出爱春、伤春情绪。接着又以对春天的体贴关怀，写春去无痕；下片写夏季的到来，先以叹问点明春天已无踪迹，进一步表现惜春的沉痛，接着又添一层烦恼和沉痛。与一般惜春之词不同，这首词不以景物描写为主，而以浪漫主义的手法，专写寻春，表达对春天的爱恋。",
    "background_gwd": "公元1103年（崇宁二年）十二月，黄庭坚至崇宁同年二月才过洞庭，五、六月间方抵达广西宜州贬所。本首词就是作于贬谪宜州的翌年，即公元1105年（崇宁四年）。",
