    "funTip": "春天的风暖暖的，吹在脸上好舒服～",
    "sceneId": "field",
    "sceneName": "草地",
    "bgTheme": "field",
    "theme": "田园",
    "sentences": [
      {
        "text": "古木阴中系短篷，",
        "py": "gǔ mù yīn zhōng xì duǎn péng",
        "trans": "",
        "words": []
      },
      {
        "text": "杖藜扶我过桥东。",
        "py": "zhàng lí fú wǒ guò qiáo dōng",
        "trans": "",
        "words": []
      },
      {
        "text": "沾衣欲湿杏花雨，",
        "py": "zhān yī yù shī xìng huā yǔ",
        "trans": "",
        "words": []
      },
      {
        "text": "吹面不寒杨柳风。",
        "py": "chuī miàn bù hán yáng liǔ fēng",
        "trans": "",
        "words": []
      }
    ],
    "translation": "在古树的浓荫下，我拴好了小小的船篷。拄着藜木拐杖，慢悠悠地走过桥东。杏花开放时节，细雨蒙蒙，沾在衣服上好像要湿了，又好像没有湿；迎面吹来的杨柳风，轻轻柔柔的，一点也不觉得寒冷。诗人用最轻柔的笔触，画出了春天最好的样子。",
    "appreciation": "这首诗最动人的地方在于它把触觉写活了。'沾衣欲湿杏花雨，吹面不寒杨柳风'两句，写出了春天雨的温柔——似湿非湿，写出了春风的体贴——似寒非寒。诗人没有写花多红、草多绿，却让人从皮肤上感受到了春天的温度和湿度。这是一首用身体去'读'的诗，小朋友读的时候闭上眼睛感受一下，仿佛自己正走在杏花春雨里。",
    "background": "志南是一位南宋的诗僧，这首诗是他晚年写的。诗僧就是当了和尚又写诗的人。他年纪很大了，腿脚不太方便，拄着藜杖走路，但是他心里一点都不老。春天来了，他驾着小船出游，把船系在古树下，独自走过小桥去赏春。这首诗记录的就是这样一次简单又美好的春日散步——年纪虽老，心却和春天一样年轻。",
    "author_info": "僧志南，南宋诗僧，生卒年不详。'志南'是他的法号。他留下的诗作很少，但这首《绝句》却成了写春天的千古名篇。朱熹曾评价说：'南诗清丽有余，格力闲暇。'意思是志南的诗清新优美，格调从容悠闲。",
    "notes": "",
