    "translation": "飞来峰上有一座高高的塔，听说站在塔顶上，��以听到雄鸡打鸣、看到旭日东升。我不怕浮云遮住远望的视线，因为我就站在最高的一层！浮云飘过来想挡住阳光，可是我不怕——我站得最高，浮云只能飘在我脚下。",
    "appreciation": "这首诗最让人佩服的是那种'不怕'的气魄。浮云可以遮住太阳，但遮不住站在最高处的人。这里的'浮云'也暗指那些阻碍自己的人或困难，'最高层'代表远大的理想和坚定的信心。小朋友遇到困难的时候，也可以想一想：如果站得更高一点，那些困难是不是就会变小了？王安石用一座山、一座塔，说出了一个人生大道理——只有站得高，才能看得远，才不会被眼前的小困难挡住。",
    "background": "王安石年轻时就胸怀大志，立志要为国家做大事。他登上飞来峰的高塔，极目远望，心中豪情万丈。那个时候他还没有当宰相，还没有推行变法，但他已经下定决心：不管将来有多少人反对他、有多少困难阻挡他，他都要站在最高处，按自己的理想去做。这首诗是他三十岁左右写的，充满了年轻人对未来的信心。",
    "author_info": "王安石（1021—1086），字介甫，号半山，临川人，北宋政治家、文学家、思想家，'唐宋八大家'之一。他学识渊博，文章简洁有力，诗歌意境深远。晚年隐居南京，诗风转向含蓄深沉。代表作有《登飞来峰》《泊船瓜洲》《梅》等。",
    "notes": "飞来峰：有两说：一说在浙江绍兴城外的宝林山。唐宋时其中有座应天塔。传说此峰是从琅琊郡东武县飞来的，故名飞来峰。一说在今浙江杭州西湖灵隐寺前。千寻塔：很高很高的塔。寻，古时长度单位，八尺为寻。闻说：听说。浮云：在山间浮动的云雾。望眼：远望的视线。眼，视线。缘：因为。",
    "tags": [
      "古诗三百首",
      "初中古诗",
      "中国诗词大会2024"
    ],
    "gwd_id": "4a272f472fee",
    "gwd_url": "https://www.guwendao.net/shiwenv_4a272f472fee.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "这首诗反映了诗人为实现自己的政治抱负而勇往直前、无所畏惧的进取精神。诗的第一句，诗人用“千寻”这一夸张的词语，借写峰上古塔之高，写出自己的立足点之高。诗的第二句，巧妙地虚写出在高塔上看到的旭日东升的辉煌景象，表现了诗人朝气蓬勃、胸怀改革大志、对前途充满信心，成为全诗感情色彩的基调。诗的后两句承接前两句写景议论抒情，使诗歌既有生动的形象又有深刻的哲理。古人常有浮云蔽日、邪臣蔽贤的忧虑，而诗人却加上“不畏”二字。表现了诗人在政治上高瞻远瞩，不畏奸邪的勇气和决心。\n后两句是全诗的精华，蕴含着深刻的哲理：人不能只为眼前的利益，应该放眼大局和长远。在写作手法上，起句写飞来峰",
    "background_gwd": "",
    "author_info_gwd": "王安石（1021年12月18日－1086年5月21日），字介甫，号半山，谥文，封荆国公。世人又称王荆公。汉族，北宋抚州临川人（今江西省抚州市临川区邓家巷人），中国北宋著名政治家、思想家、文学家、改革家，唐宋八大家之一。欧阳修称赞王安石：“翰林风月三千首，吏部文章二百年。老去自怜心尚在，后来谁与子争先。”传世文集有《王临川集》、《临川集拾遗》等。其诗文各体兼擅，词虽不多，但亦擅长，且有名作《桂枝香》等。而王荆公最得世人共传之诗句莫过于《泊船瓜洲》中的“春风又绿江南岸，明月何时照我还。”"
