    "paragraphs": [
      "秋浦长似秋，萧条使人愁。",
      "客愁不可度，行上东大楼。",
      "正西望长安，下见江水流。",
      "寄言向江水，汝意忆侬不。",
      "遥传一掬泪，为我达扬州。",
      "秋浦猿夜愁，黄山堪白头。",
      "清溪非陇水，翻作断肠流。",
      "欲去不得去，薄游成久游。",
      "何年是归日，雨泪下孤舟。",
      "秋浦锦驼鸟，人间天上稀。",
      "山鸡羞渌水，不敢照毛衣。",
      "两鬓入秋浦，一朝飒已衰。",
      "猿声催白发，长短尽成丝。",
      "秋浦多白猿，超腾若飞雪。",
      "牵引条上儿，饮弄水中月。",
      "愁作秋浦客，强看秋浦花。",
      "山川如剡县，风日似长沙。",
      "醉上山公马，寒歌宁戚牛。",
      "空吟白石烂，泪满黑貂裘。",
      "秋浦千重岭，水车岭最奇。",
      "天倾欲堕石，水拂寄生枝。",
      "江祖一片石，青天扫画屏。",
      "题诗留万古，绿字锦苔生。",
      "千千石楠树，万万女贞林。",
      "山山白鹭满，涧涧白猿吟。",
      "君莫向秋浦，猿声碎客心。",
      "逻人横鸟道，江祖出鱼梁。",
      "水急客舟疾，山花拂面香。",
      "水如一匹练，此地即平天。",
      "耐可乘明月，看花上酒船。",
      "渌水净素月，月明白鹭飞。",
      "郎听采菱女，一道夜歌归。",
      "炉火照天地，红星乱紫烟。",
      "赧郎明月夜，歌曲动寒川。",
      "白发三千丈，缘愁似个长。",
      "不知明镜里，何处得秋霜。",
      "秋浦田舍翁，采鱼水中宿。",
      "妻子张白鹇，结罝映深竹。",
      "桃波一步地，了了语声闻。",
      "黯与山僧别，低头礼白云。"
    ],
