    "paragraphs": [
      "月宫清冷桂团团，岁岁花开只自攀。",
      "共在人间说天上，不知天上忆人间。"
    ],
    "pinyinLines": [
      [
        {
          "char": "嫦",
          "py": ""
        }
      ]
    ],
    "funTip": "",
    "sceneId": "generic",
    "sceneName": "通用",
    "bgTheme": "generic",
    "theme": "节日",
    "sentences": [
      {
        "text": "月宫清冷桂团团",
        "py": "yuè gōng qīng lěng guì tuán tuán"
      },
      {
        "text": "岁岁花开只自攀",
        "py": "suì suì huā kāi zhǐ zì pān"
      },
      {
        "text": "共在人间说天上",
        "py": "gòng zài rén jiān shuō tiān shàng"
      },
      {
        "text": "不知天上忆人间",
        "py": "bù zhī tiān shàng yì rén jiān"
      }
    ],
    "translation": "烛光映照在云母屏风上，影影绰绰；银河渐渐落下去，晨星也快要消失了。住在那遥远月宫里的嫦娥仙子，应该后悔偷吃了仙丹吧？广阔的蓝天和碧海，每个夜晚都让她的心格外孤单。虽然在月亮上可以长生不老，可是没有朋友、没有亲人，这样的生活真的快乐吗？",
    "appreciation": "李商隐把嫦娥的故事写得有点忧伤。嫦娥飞到了月亮上，有了长生不老的能力，可是她孤单呀！每天面对的只有碧海青天，连个说话的人都没有。诗人好像在悄悄问小朋友：是热热闹闹地和家人在一起好呢？还是一个人拥有再多的好东西好呢？",
    "background": "嫦娥奔月是中国古老的传说：后羿的妻子嫦娥偷吃了仙丹，飞到了月亮上。李商隐借用这个故事，表达自己内心的孤独感。他一生经历坎坷，常常觉得不被人理解，就像月宫里的嫦娥一样。",
    "author_info": "李商隐（约813—约858），字义山，晚唐著名诗人。他的诗写得特别美，但有时候比较难懂，因为喜欢用典故和象征。他的爱情诗和咏物诗都很有名。",
    "notes": "攀：摘取；折。",
    "tags": [
      "神话",
      "写人",
      "嫦娥"
    ],
    "gwd_id": "ec37ba2d577a",
    "gwd_url": "https://www.guwendao.net/shiwenv_ec37ba2d577a.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "",
    "background_gwd": "",
    "author_info_gwd": "边贡（1476 ～1532）字庭实，因家居华泉附近，自号华泉子，历城（今山东济南市）人。明代著名诗人、文学家。弘治九年（1496）丙辰科进士，官至太常丞。边贡以诗著称于弘治、正德年间，与李梦阳、何景明、徐祯卿并称“弘治四杰”。后来又加上康海、王九思、王廷相，合称为明代文学“前七子”。"
