    "funTip": "同样是喜欢鱼——一个喂鱼，一个钓鱼～",
    "sceneId": "pond",
    "sceneName": "池塘",
    "bgTheme": "pond",
    "theme": "童趣",
    "sentences": [
      {
        "text": "绕池闲步看鱼游，",
        "py": "rào chí xián bù kàn yú yóu",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "正值儿童弄钓舟。",
        "py": "zhèng zhí ér tóng nòng diào zhōu",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "一种爱鱼心各异，",
        "py": "yī zhǒng ài yú xīn gè yì",
        "charCount": 8,
        "trans": "",
        "words": []
      },
      {
        "text": "我来施食尔垂钩。",
        "py": "wǒ lái shī shí ěr chuí gōu",
        "charCount": 8,
        "trans": "",
        "words": []
      }
    ],
    "translation": "白居易绕着池塘悠闲地散步，看着鱼儿在水中游来游去。他正看得入神，忽然有个小孩子撑着小船悄悄地过来，往水里偷偷撒鱼饵。那些本来自由自在的鱼儿呀，一下子就被吸引过去了。原来不只是人会被好吃的吸引，鱼儿也一样呢！看着贪吃的鱼儿，诗人忍不住笑了。",
    "appreciation": "这首诗写了一个有趣的池塘边的小场景。诗人正在欣赏鱼儿自由地游泳，一个小孩划船过来喂鱼，画面一下子就热闹了起来。白居易好像在和小朋友说：你们看，鱼儿闻到好吃的也会跑过来，是不是很可爱？简单的生活场景里藏着诗人对大自然的热爱。",
    "background": "白居易晚年住在洛阳，特别喜欢在池塘边散步看鱼。一天他看到小孩子撑船喂鱼的场景，觉得生动有趣，就用浅白的语言写下了这首小诗，记录这轻松愉快的一刻。",
    "author_info": "白居易（772—846），号香山居士，唐代大诗人。他写诗追求简单易懂，据说写完诗要念给老奶奶听，听不懂就改。他留下了《长恨歌》《琵琶行》等千古名篇。",
    "notes": "",
