    "translation": "蝉儿高高地趴在树枝上，它的嘴巴像一根细管子，吮吸着清晨的露水。它的叫声非常清脆，不是靠秋风吹送才传得远，而是因为它站得高呀！蝉的叫声从高高的梧桐树上飘下来，传得好远好远。蝉儿虽然小，但是因为它站在高处，声音就能传遍四方。做人也一样，品格高尚，自然会有影响力。",
    "appreciation": "李商隐借蝉来写自己。蝉站在高高的树上，喝的是干净的露水，叫声明亮悠远——这不正是一个品德高尚的人的写照吗？「居高声自远，非是藉秋风」是全诗最闪光的句子，告诉小朋友：真正的能力和名声来自于自身的修养，而不是依靠外部的力量。",
    "background": "李商隐一生在官场上不得志，但他始终保持着高洁的品格。这首咏蝉诗是他借蝉来明志——虽然人生坎坷，但坚守品格的初心不改。蝉在古诗词中常被用来象征高洁的人格。",
    "author_info": "李商隐（约813—约858），字义山，晚唐著名诗人。他的诗含蓄优美，善于用象征和典故，咏物诗写得特别好，常常借物来表达自己的内心世界。",
