    "translation": "我一个人坐在安静的竹林里，身边是密密的竹子。我一边弹琴，一边放声长啸，竹林里只有我的琴声和歌声在回荡。没有人知道我在这里，也没有人来打扰我。只有天上的明月，透过竹叶的缝隙照下来，柔柔地陪伴着我。一个人、一张琴、一轮明月，安安静静的，多好呀！",
    "appreciation": "这首诗读起来特别安静。「独坐」「弹琴」「长啸」，王维一个人在竹林里自得其乐。「深林人不知，明月来相照」——没有人来也不要紧，有月亮来作伴呢！这种安静的快乐，不需要很多人懂，自己开心就好。小朋友有时候是不是也喜欢一个人安安静静做自己喜欢的事呢？",
    "background": "王维晚年住在辋川别墅，那里有大片的竹林。他常在竹林里弹琴、吟诗、赏月，过着半隐居的生活。这首《竹里馆》是他《辋川集》中的一首，写出了隐居生活中与自然融为一体的宁静。",
    "author_info": "王维（约701—761），字摩诘，唐代诗人、画家、音乐家。他被称为「诗佛」，因为他的诗意境空灵，有禅意。他的山水田园诗被誉为「诗中有画，画中有诗」。",
    "notes": "竹里馆：辋川别墅胜景之一，房屋周围有竹林，故名。幽篁（huáng）：幽深的竹林。啸（xiào）：撮口发出长而清脆的声音，类似于打口哨。深林：指“幽篁”。相照：与“独坐”相应，意思是说，左右无人相伴，唯有明月似解人意，偏来相照。长啸：撮口而呼，这里指吟咏、歌唱。古代一些超逸之士常用来抒发感情。魏晋名士称吹口哨为啸。",
    "tags": [
      "唐诗三百首",
      "小学生必背古诗80首",
      "大学古诗"
    ],
    "gwd_id": "4809b5e7a16a",
    "gwd_url": "https://www.guwendao.net/shiwenv_4809b5e7a16a.aspx",
    "translation_gwd": "",
    "appreciation_gwd": "此诗写隐者的闲适生活以及情趣，描绘了诗人月下独坐、弹琴长啸的悠闲生活，遣词造句简朴清丽，传达出诗人宁静、淡泊的心情，表现了清幽宁静、高雅绝俗的境界。\n起句写诗人活动的环境非常幽静。开头一个“独”字便给读者留下了突出印象，这个“独”字也贯穿了全篇。“幽篁”指幽深的竹林。《楚辞·九歌·山鬼》说：“余处幽篁兮终不见天。”“竹里馆”顾名思义是一座建在竹林深处的房子，王维独自坐在里面。他的朋友裴迪的同题诗写道：“出入唯山鸟，幽深无世人。”仅诗的第一句就塑造了一个悠然独处者的形象。\n次句承上写诗人悠然独处，借弹琴和长啸来抒发自己的情感。我们知道王维是著名的音乐家，",
    "background_gwd": "",
    "author_info_gwd": "王维（701年－761年，一说699年—761年），字摩诘(jié)，号摩诘居士。汉族，河东蒲州（今山西运城）人，祖籍山西祁县，唐朝诗人，有“诗佛”之称。苏轼评价其：“味摩诘之诗，诗中有画；观摩诘之画，画中有诗。”开元九年（721年）中进士，任太乐丞。天宝年间，拜吏部郎中、给事中。唐肃宗乾元年间任尚书右丞，世称“王右丞”。王维是盛唐诗人的代表，今存诗400余首，重要诗作有《相思》《山居秋暝》等。王维精通佛学，受禅宗影响很大。佛教有一部《维摩诘经》，是王维名和字的由来。王维诗书画都很有名，多才多艺，音乐也很精通。与孟浩然合称“王孟”。"
